{
  "items": [
    {
      "topic": {
        "text": "Unstructured data requires pattern recognition beyond static algorithms.",
        "refs": ["Q0000"],
        "claims": [
          {
            "text": "Structured data is easier to handle than unstructured data for pattern recognition.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": null,
            "refs": ["Q0000"],
            "related_refs": []
          }
        ]
      },
      "explanation_type": {
        "text": "When dealing with images, humans identify objects by detecting features such as eyes, ears, and whiskers, regardless of their position or scale.",
        "refs": ["Q0001", "Q0002", "Q0003"],
        "claims": [
          {
            "text": "Human visual recognition relies on detecting multiple features (e.g., round eyes, pointy ears, whiskers).",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": null,
            "refs": ["Q0001"],
            "related_refs": []
          },
          {
            "text": "Feature locations and scales vary across images, so static pixel‑based rules are insufficient.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": null,
            "refs": ["Q0002", "Q0003"],
            "related_refs": []
          }
        ]
      },
      "explanation_text": {
        "text": "Neural networks can learn to detect these features irrespective of position or scale.",
        "refs": ["Q0003"],
        "claims": [
          {
            "text": "A novel approach (neural networks) is needed to detect features independent of location and scale.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": null,
            "refs": ["Q0003"],
            "related_refs": []
          }
        ]
      }
    },
    {
      "topic": {
        "text": "Analogy of students detecting specific body parts of a koala.",
        "refs": ["Q0005", "Q0006", "Q0007", "Q0008", "Q0009"],
        "claims": [
          {
            "text": "Each student is assigned to detect a specific part (eyes, nose, etc.) of the koala.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": null,
            "refs": ["Q0005", "Q0006"],
            "related_refs": []
          },
          {
            "text": "Detections are expressed as scores between 0 and 1.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": null,
            "refs": ["Q0007"],
            "related_refs": []
          },
          {
            "text": "Students are assumed to be trained before making predictions.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": null,
            "refs": ["Q0008"],
            "related_refs": []
          },
          {
            "text": "After training, each student becomes an expert detector for its assigned part.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": null,
            "refs": ["Q0009"],
            "related_refs": []
          }
        ]
      },
      "explanation_type": {
        "text": "When presented with a new image (e.g., a lion), each student outputs a low confidence score for the koala part they specialize in.",
        "refs": ["Q0010", "Q0011"],
        "claims": [
          {
            "text": "A detector trained on koala eyes gives a low score (e.g., 0.03) for a lion image.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": null,
            "refs": ["Q0010"],
            "related_refs": []
          },
          {
            "text": "Similarly, the nose detector uses a threshold (e.g., >0.5) to decide presence.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": null,
            "refs": ["Q0011"],
            "related_refs": []
          }
        ]
      },
      "explanation_text": {
        "text": "The individual part scores are combined by a higher‑level classifier (Serena) to decide if the whole face is present.",
        "refs": ["Q0013", "Q0014"],
        "claims": [
          {
            "text": "A higher‑level classifier aggregates part detections to infer the presence of the full object.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": null,
            "refs": ["Q0013", "Q0014"],
            "related_refs": []
          }
        ]
      }
    },
    {
      "topic": {
        "text": "Weighting of part contributions in the final decision.",
        "refs": ["Q0015", "Q0017", "Q0018"],
        "claims": [
          {
            "text": "The final decision can assign more weight to certain parts (e.g., face) than others.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": null,
            "refs": ["Q0015", "Q0017"],
            "related_refs": []
          },
          {
            "text": "Weighting reflects the relative importance of features for the target classification.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": null,
            "refs": ["Q0018"],
            "related_refs": []
          }
        ]
      },
      "explanation_type": null,
      "explanation_text": {
        "text": "The model can learn or be designed to give higher influence to facial features when determining a koala face.",
        "refs": ["Q0015", "Q0017", "Q0018"],
        "claims": [
          {
            "text": "Higher influence (weight) can be given to facial features in the aggregation step.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": null,
            "refs": ["Q0015", "Q0017", "Q0018"],
            "related_refs": []
          }
        ]
      }
    }
  ],
  "abstentions": [],
  "excluded": []
}
